"""Small read-only implementations of chezmoi's unmanaged/ignored commands."""
import fnmatch
import os
from pathlib import Path


_ATTRS = ("private_", "executable_", "readonly_", "encrypted_", "empty_",
          "symlink_", "modify_", "create_", "remove_", "exact_")


def target_name(name):
    # Attributes are source-state prefixes and are stripped in the target.
    changed = True
    while changed:
        changed = False
        for prefix in _ATTRS:
            if prefix.strip() and name.startswith(prefix.strip()):
                name = name[len(prefix.strip()):]
                changed = True
    if name.startswith("dot_"):
        name = "." + name[4:]
    if name.endswith(".tmpl"):
        name = name[:-5]
    return name


def _managed(source):
    result = set()
    root = Path(source)
    if not root.is_dir():
        return result
    for base, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d != ".git"]
        relbase = Path(base).relative_to(root)
        for name in dirs + files:
            if name in (".chezmoiignore", ".chezmoidata.json", ".chezmoi.toml.tmpl"):
                continue
            rel = (relbase / target_name(name)).as_posix()
            result.add(rel)
    return result


def _ignored_patterns(source):
    p = Path(source) / ".chezmoiignore"
    try:
        return [x.strip() for x in p.read_text().splitlines()
                if x.strip() and not x.lstrip().startswith("#")]
    except OSError:
        return []


def handle(command, args, source, destination):
    """Return (exit status, stdout, stderr); args excludes command/global flags."""
    nul = "-0" in args or "--nul-path-separator" in args
    absolute = "--path-style=absolute" in args or "--path-style" in args and args[args.index("--path-style") + 1:args.index("--path-style") + 2] == ["absolute"]
    tree = "-t" in args or "--tree" in args
    operands = [x for x in args if not x.startswith("-") and x not in ("absolute", "relative")]
    root = Path(destination).expanduser().resolve()
    known = _managed(source)
    if command == "ignored":
        patterns = _ignored_patterns(source)
        candidates = []
        for base, dirs, files in os.walk(root):
            dirs.sort(); files.sort()
            for n in dirs + files:
                rel = (Path(base) / n).relative_to(root).as_posix()
                if any(fnmatch.fnmatch(rel, p) or fnmatch.fnmatch(n, p) for p in patterns):
                    candidates.append(rel)
        candidates.sort()
    else:
        candidates = []
        if not operands:
            paths = [root]
        else:
            paths = []
            for operand in operands:
                p = Path(operand).expanduser()
                if not p.is_absolute(): p = root / p
                if not p.exists() and not p.is_symlink():
                    return 1, "", f"chezmoi: {operand}: no such file or directory\n"
                paths.append(p.resolve())
        for path in paths:
            if not path.exists() and not path.is_symlink():
                continue
            if path.is_dir():
                if path == root and not operands:
                    entries = list(path.iterdir())
                else:
                    entries = [path]
                for entry in entries:
                    rel = entry.relative_to(root).as_posix()
                    if rel not in known:
                        candidates.append(rel)
            else:
                rel = path.relative_to(root).as_posix()
                if rel not in known: candidates.append(rel)
        candidates = sorted(set(candidates))
    if absolute:
        candidates = [(root / p).as_posix() for p in candidates]
    if tree and candidates:
        # Preserve the path list representation; directory prefixes are already sorted.
        pass
    sep = "\0" if nul else "\n"
    out = sep.join(candidates)
    if candidates and not nul: out += "\n"
    if candidates and nul: out += "\0"
    return 0, out, ""
